def merge(intervals):
    # Sort a copy; fresh output pairs keep the input unchanged.
    ordered = sorted(intervals, key=lambda interval: interval[0])
    merged = []
    for start, end in ordered:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

solution.java:
import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        // Sort a shallow outer copy; never modify its inner arrays.
        int[][] ordered = intervals.clone();
        Arrays.sort(ordered, Comparator.comparingInt(a -> a[0]));
        List<int[]> merged = new ArrayList<>();
        for (int[] interval : ordered) {
            if (merged.isEmpty() ||
                interval[0] > merged.get(merged.size() - 1)[1]) {
                merged.add(new int[]{interval[0], interval[1]});
            } else {
                int[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], interval[1]);
            }
        }
        return merged.toArray(new int[merged.size()][]);
    }
}

solution.javascript:
function merge(intervals) {
    // Sort an outer copy and create fresh pairs for the result.
    const ordered = [...intervals].sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const [start, end] of ordered) {
        const last = merged[merged.length - 1];
        if (!last || start > last[1]) {
            merged.push([start, end]);
        } else {
            last[1] = Math.max(last[1], end);
        }
    }
    return merged;
}
